const menuButton=document.querySelector('.menu-button'),nav=document.querySelector('#main-nav');
menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
function propertyFacts(p){return [p.bedrooms?`${p.bedrooms} bedrooms`:null,p.bathrooms?`${p.bathrooms} bathrooms`:null,p.toilets?`${p.toilets} toilets`:null,p.land_area||null,p.dimensions||null,p.parking?`${p.parking_spaces||''} parking ${p.parking_spaces==1?'space':'spaces'}`.trim():null,p.furnishing||null].filter(Boolean)}
function startHeroSlider(slides){if(!slides.length)return;const hero=document.querySelector('.hero'),eyebrow=document.querySelector('#hero-eyebrow'),headline=document.querySelector('#hero-headline'),subtitle=document.querySelector('#hero-subtitle'),primary=document.querySelector('#hero-primary'),secondary=document.querySelector('#hero-secondary'),controls=document.querySelector('#hero-slider-controls');let current=0,timer;
  controls.innerHTML=slides.map((_,i)=>`<button type="button" aria-label="Show slide ${i+1}" data-slide="${i}"></button>`).join('');
  const show=i=>{const s=slides[i];current=i;hero.classList.add('changing');setTimeout(()=>{hero.style.backgroundImage=`linear-gradient(90deg,rgba(10,13,9,.9),rgba(10,13,9,.56) 45%,rgba(10,13,9,.12)),url('${String(s.image_url).replace(/'/g,'%27')}')`;eyebrow.textContent=s.eyebrow;headline.textContent=s.headline;subtitle.textContent=s.subtitle||'';primary.textContent=s.primary_label||'Explore properties';primary.href=s.primary_url||'#properties';secondary.style.display=s.secondary_label?'':'none';secondary.innerHTML=`${escapeHtml(s.secondary_label||'')} <span>→</span>`;secondary.href=s.secondary_url||'#appointment';controls.querySelectorAll('button').forEach((b,n)=>b.classList.toggle('active',n===i));hero.classList.remove('changing')},180)};
  const cycle=()=>{clearInterval(timer);if(slides.length>1&&!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>show((current+1)%slides.length),7000)};
  controls.onclick=e=>{if(e.target.dataset.slide!==undefined){show(Number(e.target.dataset.slide));cycle()}};show(0);cycle();
}
async function hydrate(){try{
  const [properties,posts,slides]=await Promise.all([fetch('/api/properties').then(r=>r.ok?r.json():[]),fetch('/api/posts').then(r=>r.ok?r.json():[]),fetch('/api/hero-slides').then(r=>r.ok?r.json():[])]);
  startHeroSlider(slides);
  if(properties.length)document.querySelector('.property-grid').innerHTML=properties.map(p=>`<article class="property-card ${p.featured?'featured':''}"><div class="property-image" style="background-image:url('${escapeHtml(p.image_url||'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1000&q=85')}')"><span>${escapeHtml(p.status==='published'?p.purpose:p.status)}</span></div><div class="property-copy"><p class="property-type">${escapeHtml(p.property_type)}</p><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.description)}</p><p class="property-facts">${propertyFacts(p).map(escapeHtml).join(' · ')}</p>${p.amenities?`<p><strong>Amenities:</strong> ${escapeHtml(p.amenities)}</p>`:''}<div class="property-meta"><span>${escapeHtml(p.location)}${p.price?` · ${escapeHtml(p.price)}`:''}</span><a href="#contact">Enquire →</a></div></div></article>`).join('');
  if(posts.length)document.querySelector('.blog-grid').innerHTML=posts.slice(0,4).map(p=>`<article><div class="blog-image" style="background-image:url('${escapeHtml(p.image_url||'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1100&q=85')}')"></div><p class="date">${escapeHtml(p.category)} · ${new Date(p.published_at||p.created_at).toLocaleDateString()}</p><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.excerpt)}</p><a href="#contact">Read article →</a></article>`).join('');
}catch{}}
document.querySelector('#booking-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,status=form.querySelector('.form-status');status.textContent='Sending…';try{const r=await fetch('/api/enquiries',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!r.ok)throw new Error();status.textContent='Thank you. Your appointment request has been received.';form.reset()}catch{status.textContent='Please call +233 55 247 5643 to complete your request.'}});
hydrate();
